#!/usr/bin/env python3
"""
Predator 3D ASCII renderer.

Generated from the supplied Acer Predator emblem.
Runtime dependencies: Python 3 standard library only.
"""

import math
import shutil
import sys
import time

MASK = ['..........................................................', '#........................................................#', '#........................................................#', '##......................................................##', '##......................................................##', '###....................................................###', '###....................................................###', '###....................................................###', '####..................................................####', '####..................................................####', '#####.....................#....#.....................#####', '#####.....................#....#.....................#####', '######....................#....#....................######', '######...................##....##...................######', '#######..................##....##..................#######', '#######..................##....##..................#######', '########................###....###................########', '#########...............###....###...............#########', '##########..............###....###..............##########', '###########............####....####............###########', '############...........#####...####...........############', '#############.........#####....#####.........#############', '##############........#####....#####........##############', '###############.......#####....#####.......###############', '################.....######....######.....################', '#################....#######...######....#################', '##################..########...#######..##################', '###################.#######....#######.###################', '###########################....###########################', '########.##################....###########################', '########..#################....#################..########', '#########.#################....#################.#########', '#########..#################...################..#########', '#########...###############....###############...#########', '#########...###############....###############...#########', '#########....##############....##############....#########', '#########.....#############....#############.....#########', '#########.....#############....#############.....#########', '#########......############....############......#########', '#########......############....############......#########', '##########.....############....############.....##########', '###########....############....############....###########', '.###########...############....############...###########.', '..###########..############....############..###########..', '...#########...############....############...#########...', '....########...############....############...########....', '.....#######...############....############...#######.....', '......######...############....############...######......', '.......#####...############....############...#####.......', '........####...############....############...####........', '..........##...#############...############...##..........', '...........##..#############...############..##...........', '...........#...############....############...#...........', '...............###########......###########...............', '...............##########........##########...............', '...............#########..........#########...............', '...............########............########...............', '...............#######..............#######...............', '...............######................######...............', '...............#####..................#####...............', '...............#####..................#####...............', '...............#####..................#####...............', '...............####....................####...............', '...............####....................####...............', '...............###......................###...............', '...............###......................###...............', '...............##........................##...............', '...............##........................##...............', '...............##........................##...............', '...............#..........................#...............', '...............#..........................#...............', '..........................................................']
H = len(MASK)
W = len(MASK[0])

# Dense-to-light characters. The renderer chooses one based on lighting.
RAMP = " .:-=+*#%@"

# Terminal color: bright blue/purple-ish ANSI. Set to "" for monochrome.
COLOR = "\033[38;5;111m"
RESET = "\033[0m"

# Animation controls.
FPS = 24
SPEED = 1.25
X_SCALE = 1.85       # compensates for terminal character aspect ratio
Y_SCALE = 1.00
PERSPECTIVE = 0.22
DEPTH = 0.18

def terminal_size():
    size = shutil.get_terminal_size((100, 30))
    return size.columns, size.lines

def build_points():
    points = []
    for j, row in enumerate(MASK):
        for i, value in enumerate(row):
            if value == "#":
                # Normalize to [-1, 1].
                x = (i / (W - 1)) * 2.0 - 1.0
                y = (j / (H - 1)) * 2.0 - 1.0
                # Slightly round the silhouette into a continuous surface.
                points.append((x, y))
    return points

POINTS = build_points()

def frame(angle, cols, lines):
    # Keep enough room for the animation when run standalone.
    out_w = min(62, max(28, cols - 4))
    out_h = min(28, max(12, lines - 3))

    # Render into a character grid.
    grid = [[" " for _ in range(out_w)] for _ in range(out_h)]

    ca = math.cos(angle)
    sa = math.sin(angle)

    # A little depth is added so the emblem has a visible rim during rotation.
    for x, y in POINTS:
        # Flat emblem rotated around the vertical axis.
        xr = x * ca
        zr = x * sa

        # Perspective projection.
        scale = 1.0 / max(0.55, 1.0 - zr * PERSPECTIVE)
        xp = xr * scale * X_SCALE
        yp = y * scale * Y_SCALE

        gx = int((xp + 1.0) * 0.5 * (out_w - 1))
        gy = int((yp + 1.0) * 0.5 * (out_h - 1))

        if 0 <= gx < out_w and 0 <= gy < out_h:
            # Lighting follows the rotating surface.
            light = 0.35 + 0.65 * max(0.0, ca)
            # Add a rim highlight near the silhouette edges.
            edge = 0.18 * (1.0 - abs(x))
            value = min(1.0, light + edge)
            idx = min(len(RAMP) - 1, int(value * (len(RAMP) - 1)))
            grid[gy][gx] = RAMP[idx]

    # Double horizontal density to make the emblem less vertically stretched.
    lines_out = []
    for row in grid:
        s = "".join(row)
        lines_out.append(s)

    return "\n".join(lines_out)

def main():
    cols, lines = terminal_size()
    start = time.monotonic()

    # Hide cursor and clear the terminal.
    sys.stdout.write("\033[?25l\033[2J")
    sys.stdout.flush()

    try:
        while True:
            cols, lines = terminal_size()
            angle = (time.monotonic() - start) * SPEED

            art = frame(angle, cols, lines)

            # Draw from the top-left every frame.
            sys.stdout.write("\033[H")
            sys.stdout.write(COLOR)
            sys.stdout.write(art)
            sys.stdout.write(RESET)
            sys.stdout.flush()

            time.sleep(1.0 / FPS)

    except KeyboardInterrupt:
        pass
    finally:
        sys.stdout.write("\033[0m\033[?25h\033[H\033[2J")
        sys.stdout.flush()

if __name__ == "__main__":
    main()
